const MD_clip=(px,py,dx,dy,x,y,w,h)=>{let t0=-1e9,t1=1e9;[[dx,px,x,x+w],[dy,py,y,y+h]].forEach(([d,p,lo,hi])=>{if(Math.abs(d)<1e-9){if(p<lo||p>hi){t0=1;t1=0}}else{let a=(lo-p)/d,b=(hi-p)/d;if(a>b)[a,b]=[b,a];t0=Math.max(t0,a);t1=Math.min(t1,b)}});return t1>t0?[px+t0*dx,py+t0*dy,px+t1*dx,py+t1*dy]:null};
/* helical teeth seen from the side: lines at deg to the horizontal axis (hand 1 rises to the right), vertical spacing pitch */
