const MD_worm=(x,y,w,h,col=MD_STEEL)=>{let s=`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${Math.min(12,h/4)}" fill="${MD_LIGHT}" stroke="${col}" stroke-width="3"/>`;const p=Math.max(12,h*.45);for(let xx=x+p*.6;xx<x+w-4;xx+=p){s+=MD_L(xx,y+3,xx+h*.32,y+h-3,col,3)}return s};

